import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, sys.stdin.readline().split())))

    # Find all pairs and their positions
    pairs = {}
    for i in range(n):
        for j in range(m):
            val = grid[i][j]
            if val not in pairs:
                pairs[val] = []
            pairs[val].append((i, j))

    # Check if a pair is already adjacent
    def is_adjacent(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1

    # BFS to find minimum steps to move from start to target, avoiding obstacles
    def bfs(start, target, obstacles):
        if start == target:
            return 0
        visited = set()
        q = deque()
        q.append((start[0], start[1], 0))
        visited.add((start[0], start[1]))
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while q:
            x, y, steps = q.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m:
                    if (nx, ny) == target:
                        return steps + 1
                    if (nx, ny) not in visited and (nx, ny) not in obstacles:
                        visited.add((nx, ny))
                        q.append((nx, ny, steps + 1))
        return float('inf')

    # Calculate total moves needed
    total_moves = 0
    for val, positions in pairs.items():
        a, b = positions
        if is_adjacent(a, b):
            continue
        # Try moving a to b's adjacent cell or b to a's adjacent cell
        # Obstacles are all other shoes except the pair being moved
        obstacles = set()
        for v, pos in pairs.items():
            if v != val:
                obstacles.add(pos[0])
                obstacles.add(pos[1])
        # Find adjacent cells to b
        min_steps = float('inf')
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = b[0] + dx, b[1] + dy
            if 0 <= nx < n and 0 <= ny < m:
                if (nx, ny) != a and (nx, ny) not in obstacles:
                    steps = bfs(a, (nx, ny), obstacles)
                    if steps < min_steps:
                        min_steps = steps
        # Find adjacent cells to a
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = a[0] + dx, a[1] + dy
            if 0 <= nx < n and 0 <= ny < m:
                if (nx, ny) != b and (nx, ny) not in obstacles:
                    steps = bfs(b, (nx, ny), obstacles)
                    if steps < min_steps:
                        min_steps = steps
        if min_steps != float('inf'):
            total_moves += min_steps

    print(total_moves)

if __name__ == "__main__":
    main()
